const CURRENT_VERSION: &str = "v1";
const V2_HELLO_PREFIX: &str = "v:2:hello:";

pub enum Msg {
    Ping,
    Hello(String),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    match bytes {
        "ping" | "v1:ping" => Ok(Msg::Ping),
        _ if bytes.starts_with(V2_HELLO_PREFIX) => {
            Ok(Msg::Hello(bytes[V2_HELLO_PREFIX.len()..].to_owned()))
        }
        _ => {
            eprintln!("protocol decode error: unknown message body {bytes:?}");
            Err("unknown".into())
        }
    }
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => format!("{CURRENT_VERSION}:ping"),
        Msg::Hello(text) => format!("{V2_HELLO_PREFIX}{text}"),
    }
}

